   n('toc-promo-'+part).textContent=t(key+part[0].toUpperCase()+part.slice(1));
  n('toc-promo-action').hidden=key!=='official';
  n('toc-promo-action').textContent=key==='official'?t('officialAction'):'';
 }
}
